package tvhome.core.ui

// Generated by tools/art/render_backdrops.py from the shipped hero_*.webp images. Do not edit by hand.

/**
 * The brightest pixel of each backdrop image inside the hero text zones (HeroZones: top strip, left, right card),
 * 0xRRGGBB. GlanceTokensTest composites it over each theme's scrim at the R3 brightness and asserts 7:1.
 */
object BackdropPeaks {
    fun of(motif: HeroMotif): Int = when (motif) {
        HeroMotif.DAWN -> 0x726166
        HeroMotif.DAY -> 0x4A72A2
        HeroMotif.SUNSET -> 0x925757
        HeroMotif.STARS -> 0xB4C4E3
        HeroMotif.MOON_BATS -> 0xFFFFF0
        HeroMotif.SNOW -> 0xFFFFFF
        HeroMotif.GAME -> 0xD2C3C1
        HeroMotif.ARENA -> 0xFFBB47
    }
}
